package br.com.trama.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="notificacao_artesao") public class NotificacaoArtesao { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="id_artesao",nullable=false) private Artesao artesao; @ManyToOne(optional=false) @JoinColumn(name="id_cotacao",nullable=false) private CotacaoCorporativa cotacao; @Column(nullable=false,length=300) private String mensagem; @Column(name="data_criacao",nullable=false) private LocalDateTime dataCriacao; public NotificacaoArtesao(){} public void setArtesao(Artesao v){artesao=v;} public void setCotacao(CotacaoCorporativa v){cotacao=v;} public void setMensagem(String v){mensagem=v;} public void setDataCriacao(LocalDateTime v){dataCriacao=v;} }
